mapper.select:
SELECT id, account_id, symbol, direction, threshold, status, triggered_on, created_on, updated_on FROM tradingsystem.price_alerts WHERE account_id = #{accountId}
AND status = #{status}
ORDER BY created_on DESC, id DESC

mapper.delete:
DELETE FROM tradingsystem.price_alerts
WHERE account_id = #{accountId}
  AND id = #{alertId}
